@Service
public class OrderService {
    @Autowired private DataSource dataSource;
    @Autowired private RestTemplate restTemplate;

    @Transactional
    public OrderResult processOrder(OrderRequest request) {
        // BUG: Holding JDBC connection across slow external network call
        String fraudCheck = restTemplate.getForObject("http://fraud-service/check/" + request.userId(), String.class);
        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement ps = conn.prepareStatement("INSERT INTO orders (id, user_id, amount) VALUES (?, ?, ?)");
            ps.setString(1, request.id());
            ps.setString(2, request.userId());
            ps.setBigDecimal(3, request.amount());
            ps.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
        return new OrderResult(request.id(), "PROCESSED");
    }
}

